use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    for i in 0..(limit + 1) {
        sieve.push(true)
        counts.push(0)
        largest.push(0)
    }
    let mut i: int = 2
    while i * i <= limit {
        if sieve[i as usize] {
            let mut j: int = i * i
            while j <= limit {
                sieve[j as usize] = false
                j += i
            }
        }
        i += 1
    }
    let mut c: int = 0
    let mut last: int = 0
    for k in 0..(limit + 1) {
        if k >= 2 && sieve[k as usize] {
            c += 1
            last = k
        }
        counts[k as usize] = c
        largest[k as usize] = last
    }
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n as usize]} ${largest[n as usize]}")
        }
    }
}

